import{_ as p,C as d,o as a,c as m,j as c,a as n,G as t,a3 as o,b as r,w as i,a9 as s}from"./chunks/framework.exbasbhr.js";const v=JSON.parse('{"title":"Deployment and Maintenance","description":"Deployment and Maintenance","frontmatter":{"date":"2026-05-05T00:00:00.000Z","author":["Makitoid","Qoder"],"title":"Deployment and Maintenance","description":"Deployment and Maintenance"},"headers":[],"relativePath":"en/dev/deployment/index.md","filePath":"en/dev/deployment/index.md"}'),g={name:"en/dev/deployment/index.md"};function h(A,e,C,b,f,k){const u=d("ArticleMetadata"),l=d("Mermaid");return a(),m("div",null,[e[4]||(e[4]=c("h1",{id:"deployment-and-maintenance",tabindex:"-1"},[n("Deployment and Maintenance "),c("a",{class:"header-anchor",href:"#deployment-and-maintenance","aria-label":'Permalink to "Deployment and Maintenance"'},"​")],-1)),t(u),e[5]||(e[5]=o('<h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>This document is oriented towards the deployment and maintenance teams of InkCanvasForClass. It provides a complete practical guide covering build configurations, release workflows, installer creation, dependency management, version control and release channels, auto-update mechanisms, logging and monitoring, security hardening, troubleshooting, and maintenance tools. The document is strictly based on the actual source code and configuration files in the repository to ensure that it is actionable and reproducible.</p><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><p>InkCanvasForClass is a WPF application based on .NET 6, utilizing a multi-project combination and packaging strategy. The core project is located at <code>Ink Canvas/InkCanvasForClass.csproj</code>, and supporting resources, control libraries, and auxiliary modules are located in sub-projects such as <code>InkCanvas.Controls</code>, <code>InkCanvas.PluginSdk</code>, and <code>InkCanvas.IACoreHelper</code>. The project implements embedded packaging via Costura.Fody to reduce external dependency exposure; controls UAC and compatibility via <code>app.manifest</code>; and pins dependency versions via <code>packages.lock.json</code> to ensure reproducible builds.</p>',4)),(a(),r(s,null,{default:i(()=>[t(l,{id:"mermaid-15",class:"mermaid",graph:"graph%20TB%0Asubgraph%20%22InkCanvasForClass%20Application%22%0AA%5B%22InkCanvasForClass.csproj%22%5D%0AB%5B%22app.manifest%22%5D%0AC%5B%22FodyWeavers.xml%22%5D%0AD%5B%22packages.lock.json%22%5D%0AE%5B%22App.config%22%5D%0Aend%0Asubgraph%20%22Sub-projects%22%0AF%5B%22InkCanvas.Controls.csproj%22%5D%0AG%5B%22InkCanvas.PluginSdk.csproj%22%5D%0AH%5B%22InkCanvas.IACoreHelper.csproj%22%5D%0Aend%0AA%20--%3E%20F%0AA%20--%3E%20G%0AA%20--%3E%20H%0AA%20-.-%3E%20C%0AA%20-.-%3E%20B%0AA%20-.-%3E%20D%0AA%20-.-%3E%20E%0A"})]),fallback:i(()=>e[0]||(e[0]=[n(" Loading... ")])),_:1})),e[6]||(e[6]=o('<h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li>Build and Packaging <ul><li>Multi-target platforms: win-x86, win-x64, win-arm64</li><li>Platform identifier and output type: WinExe</li><li>Dependency pinning: RestorePackagesWithLockFile=true</li><li>Packaging strategy: Costura.Fody embeds third-party assemblies, IACore series DLLs are embedded via EmbeddedResource</li><li>Manifest and manifest injection: app.manifest injection, CopyIACoreHelper target copies the IACoreHelper executable during the build phase</li></ul></li><li>Auto-Update <ul><li>Multi-channel and multi-line groups: Release/Preview/Beta channels, with each channel containing multiple download lines</li><li>Speed testing and optimization: Concurrent HEAD request speed tests, cached for 15 minutes, prioritizing the inkeys line</li><li>Download and overwrite: Overwrites according to a file whitelist, supports x64 suffix concatenation</li></ul></li><li>Logs and Exceptions <ul><li>Logs: Unified writing to Log.txt or archived by launch time, supporting size limit cleanup</li><li>Exceptions: Centralized processing and graded logging, distinguishing between continuation-allowed and fatal exceptions</li></ul></li><li>Security and Configuration <ul><li>Password and TOTP: PBKDF2 derivation and constant-time comparison, TOTP 6-digit dynamic verification code</li><li>Configuration files: Support for multiple configuration files saving, switching, and hot reloading</li></ul></li><li>Runtime and Compatibility <ul><li>.NET 6 target framework, Windows 10 minimum version constraint</li><li>UAC policy: asInvoker, disabling virtualization to improve compatibility</li><li>Legacy runtime compatibility: App.config enables Legacy V2 activation policy</li></ul></li></ul><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>The diagram below shows the deployment and maintenance related architecture of the application: build phase (MSBuild + Costura + manifest injection), runtime phase (auto-update, logging, exceptions, security, and configuration management), and release channels (multi-line groups).</p>',4)),(a(),r(s,null,{default:i(()=>[t(l,{id:"mermaid-137",class:"mermaid",graph:"graph%20TB%0Asubgraph%20%22Build%20Phase%22%0AMS%5B%22MSBuild%20Properties%20and%20Targets%22%5D%0ACF%5B%22Costura.Fody%20Embedding%22%5D%0AMF%5B%22app.manifest%20Injection%22%5D%0APL%5B%22packages.lock.json%20Pinned%20Dependencies%22%5D%0Aend%0Asubgraph%20%22Runtime%20Phase%22%0AAU%5B%22Auto-Update%20Module%22%5D%0ALG%5B%22Log%20Module%22%5D%0AEH%5B%22Exception%20Handling%20Module%22%5D%0ASM%5B%22Security%20and%20Authentication%20Module%22%5D%0ACP%5B%22Configuration%20File%20Management%20Module%22%5D%0Aend%0Asubgraph%20%22Release%20Channels%22%0ARL%5B%22Release%20Line%20Group%22%5D%0APV%5B%22Preview%20Line%20Group%22%5D%0ABE%5B%22Beta%20Line%20Group%22%5D%0Aend%0AMS%20--%3E%20CF%0AMS%20--%3E%20MF%0AMS%20--%3E%20PL%0ACF%20--%3E%20AU%0AMF%20--%3E%20AU%0AAU%20--%3E%20RL%0AAU%20--%3E%20PV%0AAU%20--%3E%20BE%0AAU%20--%3E%20LG%0AAU%20--%3E%20EH%0AAU%20--%3E%20SM%0AAU%20--%3E%20CP%0A"})]),fallback:i(()=>e[1]||(e[1]=[n(" Loading... ")])),_:1})),e[7]||(e[7]=o('<h2 id="detailed-component-analysis" tabindex="-1">Detailed Component Analysis <a class="header-anchor" href="#detailed-component-analysis" aria-label="Permalink to &quot;Detailed Component Analysis&quot;">​</a></h2><h3 id="build-and-release-configurations-msbuild-and-packaging" tabindex="-1">Build and Release Configurations (MSBuild and Packaging) <a class="header-anchor" href="#build-and-release-configurations-msbuild-and-packaging" aria-label="Permalink to &quot;Build and Release Configurations (MSBuild and Packaging)&quot;">​</a></h3><ul><li>Multi-platform and Target Framework <ul><li>RuntimeIdentifiers specifies win-x86/win-x64/win-arm64</li><li>TargetFramework is net6.0-windows10.0.19041.0</li><li>UseWPF/UseWindowsForms enabled</li></ul></li><li>Packaging and Embedding <ul><li>Costura.Fody embeds third-party assemblies, excluding IACore/IALoader/IAWinFX</li><li>IACore series DLLs are embedded via EmbeddedResource</li><li>CopyIACoreHelper target copies the IACoreHelper output to the running directory during build phase</li></ul></li><li>Dependency Pinning and Versioning <ul><li>RestorePackagesWithLockFile=true</li><li>packages.lock.json pins dependency versions to prevent drift</li></ul></li><li>Manifest and UAC <ul><li>app.manifest sets requestedExecutionLevel to asInvoker, disabling virtualization</li><li>Common-Controls dependency declaration</li></ul></li><li>Legacy Runtime Compatibility <ul><li>App.config enables Legacy V2 activation policy, compatible with old .NET Framework runtimes</li></ul></li></ul>',3)),(a(),r(s,null,{default:i(()=>[t(l,{id:"mermaid-236",class:"mermaid",graph:"flowchart%20TD%0AStart(%5B%22Start%20Build%22%5D)%20--%3E%20RID%5B%22Set%20RuntimeIdentifiers%22%5D%0ARID%20--%3E%20TF%5B%22Set%20TargetFramework%22%5D%0ATF%20--%3E%20PKG%5B%22RestorePackagesWithLockFile%22%5D%0APKG%20--%3E%20COST%5B%22Costura%20Embeds%20Third-Party%20Assemblies%22%5D%0ACOST%20--%3E%20EMB%5B%22EmbeddedResource%20Embeds%20IACore%20DLLs%22%5D%0AEMB%20--%3E%20MAN%5B%22app.manifest%20Injection%22%5D%0AMAN%20--%3E%20COPY%5B%22Build%20Target%20CopyIACoreHelper%22%5D%0ACOPY%20--%3E%20OUT%5B%22Output%20WinExe%20Executable%22%5D%0AOUT%20--%3E%20End(%5B%22Complete%22%5D)%0A"})]),fallback:i(()=>e[2]||(e[2]=[n(" Loading... ")])),_:1})),e[8]||(e[8]=o('<h2 id="dependency-analysis" tabindex="-1">Dependency Analysis <a class="header-anchor" href="#dependency-analysis" aria-label="Permalink to &quot;Dependency Analysis&quot;">​</a></h2><ul><li>Project Dependencies <ul><li>InkCanvasForClass.csproj depends on InkCanvas.Controls and InkCanvas.PluginSdk</li><li>IACoreHelper acts as an independent project, copied to the running directory after building</li></ul></li><li>Third-Party Dependencies <ul><li>WPF/WinUI, notifications, PowerPoint interop, JSON, dependency injection, camera and video processing, WebDAV client, Sentry crash reporting, etc.</li></ul></li><li>Dependency Pinning <ul><li>packages.lock.json pins versions to avoid build drift</li></ul></li></ul>',2)),(a(),r(s,null,{default:i(()=>[t(l,{id:"mermaid-283",class:"mermaid",graph:"graph%20LR%0AICC%5B%22InkCanvasForClass.csproj%22%5D%20--%3E%20CTRL%5B%22InkCanvas.Controls.csproj%22%5D%0AICC%20--%3E%20SDK%5B%22InkCanvas.PluginSdk.csproj%22%5D%0AICC%20-.-%3E%20IAC%5B%22InkCanvas.IACoreHelper.csproj%22%5D%0AICC%20-.-%3E%20PKG%5B%22packages.lock.json%22%5D%0A"})]),fallback:i(()=>e[3]||(e[3]=[n(" Loading... ")])),_:1})),e[9]||(e[9]=o('<h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><ul><li>Auto-Update Speed Test Cache: 15-minute TTL, reducing frequent speed test overhead</li><li>Concurrent Speed Tests: Concurrent HEAD requests across multiple line groups, shortening selection time</li><li>Embedded Packaging: Reduces external dependency lookup and loading overhead</li><li>Log Rotation: Cleaned by size to prevent disk bloat from affecting IO</li><li>UAC Policy: asInvoker disables virtualization, reducing privilege switching and compatibility issues</li></ul><p>[This section is general guidance, no specific file references needed]</p><h2 id="troubleshooting-guide" tabindex="-1">Troubleshooting Guide <a class="header-anchor" href="#troubleshooting-guide" aria-label="Permalink to &quot;Troubleshooting Guide&quot;">​</a></h2><ul><li>Launch Failure <ul><li>Check if the .NET 6 runtime is installed</li><li>If missing, install .NET 6.0 or higher</li></ul></li><li>PowerPoint Mode Switching Exception <ul><li>Confirm that Office is activated</li><li>Ensure PowerPoint and the application run at the same privilege level</li></ul></li><li>Icon Display Issues (below Windows 10) <ul><li>Install Segoe MDL2 font</li></ul></li><li>Auto-Update Failure <ul><li>Check network connectivity and proxy settings</li><li>Check the log files to locate specific errors</li></ul></li><li>Configuration File Corruption <ul><li>Use the multi-configuration feature to restore or delete and recreate the configuration</li></ul></li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The deployment and maintenance of InkCanvasForClass revolve around &quot;reproducible builds, observable, rollback-ready, and auditable&quot;: stable packaging via MSBuild and Costura; update reliability via multi-line groups and speed test caching; observability via logging and exception handling; safety via passwords and TOTP; and maintainability via multi-configuration files and hot reloading. Combining the workflows and best practices in this document, the full lifecycle from build to release can be automated and standardized efficiently.</p><p>[This section is a summary, no specific file references needed]</p><h2 id="appendix" tabindex="-1">Appendix <a class="header-anchor" href="#appendix" aria-label="Permalink to &quot;Appendix&quot;">​</a></h2><h3 id="a-build-and-release-process-step-by-step" tabindex="-1">A. Build and Release Process (Step-by-Step) <a class="header-anchor" href="#a-build-and-release-process-step-by-step" aria-label="Permalink to &quot;A. Build and Release Process (Step-by-Step)&quot;">​</a></h3><ul><li>Preparation <ul><li>Ensure .NET 6 SDK, MSBuild, and Git toolchains are ready</li><li>Verify packages.lock.json and Fody/Costura configurations</li></ul></li><li>Building <ul><li>Restore dependencies: <code>dotnet restore --locked-mode</code></li><li>Build: <code>dotnet build -c Release -r win-x64 --self-contained true -p:IncludeNativeLibrariesForSelfExtract=true</code></li><li>Generate installer: Package using tools like Inno Setup or WiX (based on project requirements)</li></ul></li><li>Release <ul><li>Upload version files and changelogs to the release channels</li><li>Update version detection files and download URLs</li></ul></li></ul>',11))])}const P=p(g,[["render",h]]);export{v as __pageData,P as default};
